"""AST node classes produced by ``minidb.parser``."""
from __future__ import annotations

from dataclasses import dataclass, field
from typing import Optional, Union


# ---------------------------------------------------------------- expressions

class Expr:
    """Base class of expression nodes."""


@dataclass(eq=False)
class Literal(Expr):
    value: object  # None, bool, int, float or str


@dataclass(eq=False)
class ColumnRef(Expr):
    table: Optional[str]
    name: str


@dataclass(eq=False)
class Unary(Expr):
    op: str  # '-', '+'
    operand: Expr


@dataclass(eq=False)
class Not(Expr):
    operand: Expr


@dataclass(eq=False)
class Binary(Expr):
    op: str  # OR AND = <> < <= > >= || + - * / % LIKE  ('!=' is normalised to '<>')
    left: Expr
    right: Expr


@dataclass(eq=False)
class IsNull(Expr):
    operand: Expr
    negated: bool


@dataclass(eq=False)
class Between(Expr):
    operand: Expr
    low: Expr
    high: Expr
    negated: bool


@dataclass(eq=False)
class InList(Expr):
    operand: Expr
    items: list[Expr]
    negated: bool


@dataclass(eq=False)
class FuncCall(Expr):
    name: str            # lower case
    args: list[Expr]
    distinct: bool = False
    star: bool = False   # COUNT(*)


# ---------------------------------------------------------------- SELECT parts

@dataclass(eq=False)
class Star:
    table: Optional[str]  # None for '*', else the qualifier of 'x.*'


@dataclass(eq=False)
class SelectItem:
    expr: Expr
    alias: Optional[str]


@dataclass(eq=False)
class TableRef:
    name: str
    alias: Optional[str]

    @property
    def exposed(self) -> str:
        return self.alias or self.name


@dataclass(eq=False)
class Join:
    kind: str  # INNER, LEFT, CROSS
    table: TableRef
    on: Optional[Expr]


@dataclass(eq=False)
class FromClause:
    first: TableRef
    joins: list[Join] = field(default_factory=list)


@dataclass(eq=False)
class OrderItem:
    expr: Expr
    desc: bool
    bare: bool  # the item was a single token (bare integer literal or bare identifier)


@dataclass(eq=False)
class Select:
    distinct: bool
    items: list[Union[SelectItem, Star]]
    from_: Optional[FromClause] = None
    where: Optional[Expr] = None
    group_by: list[ColumnRef] = field(default_factory=list)
    having: Optional[Expr] = None
    order_by: list[OrderItem] = field(default_factory=list)
    limit: Optional[int] = None
    offset: Optional[int] = None


# ---------------------------------------------------------------- other statements

@dataclass(eq=False)
class ColumnDef:
    name: str
    type: str  # INTEGER, REAL, TEXT, BOOLEAN
    primary_key: bool = False
    not_null: bool = False
    unique: bool = False
    has_default: bool = False
    default: object = None


@dataclass(eq=False)
class CreateTable:
    name: str
    columns: list[ColumnDef]


@dataclass(eq=False)
class DropTable:
    name: str


@dataclass(eq=False)
class Insert:
    table: str
    columns: Optional[list[str]]
    rows: list[list[Expr]]


@dataclass(eq=False)
class Update:
    table: str
    assignments: list[tuple[str, Expr]]
    where: Optional[Expr]


@dataclass(eq=False)
class Delete:
    table: str
    where: Optional[Expr]


Statement = Union[Select, CreateTable, DropTable, Insert, Update, Delete]

