import random, sqlite3, sys
sys.path.insert(0, '.')
from minidb.engine import Engine
from minidb.protocol import DBError

def gen_expr(r, cols, depth=0):
    if depth > 2 or r.random() < 0.3:
        return r.choice(cols + [str(r.randint(-3, 5)), 'NULL'])
    op = r.choice(['+', '-', '*', '/', '%'])
    return f"({gen_expr(r, cols, depth+1)} {op} {gen_expr(r, cols, depth+1)})"

def gen_cond(r, cols, depth=0):
    k = r.random()
    if depth > 1 or k < 0.5:
        op = r.choice(['=', '<>', '<', '<=', '>', '>='])
        c = f"{gen_expr(r, cols, 2)} {op} {gen_expr(r, cols, 2)}"
        if r.random() < 0.15: c = f"{r.choice(cols)} IS NULL"
        if r.random() < 0.15: c = f"{r.choice(cols)} IN ({r.randint(0,3)}, {r.choice(['NULL','2'])})"
        if r.random() < 0.1: c = f"{r.choice(cols)} BETWEEN {r.randint(-1,2)} AND {r.randint(1,4)}"
        return c
    if k < 0.65: return f"NOT ({gen_cond(r, cols, depth+1)})"
    return f"({gen_cond(r, cols, depth+1)} {r.choice(['AND','OR'])} {gen_cond(r, cols, depth+1)})"

def run(seed):
    r = random.Random(seed)
    m, s = Engine(), sqlite3.connect(':memory:')
    for t in ('a', 'b'):
        ddl = f"CREATE TABLE {t} (x INTEGER, y INTEGER)"
        m.execute(ddl); s.execute(ddl)
        vals = ", ".join(f"({r.choice(['NULL', r.randint(0,4)])}, {r.choice(['NULL', r.randint(-2,4)])})" for _ in range(r.randint(0, 6)))
        if vals:
            m.execute(f"INSERT INTO {t} VALUES {vals}"); s.execute(f"INSERT INTO {t} VALUES {vals}")
    kind = r.choice(['plain', 'join', 'left', 'group', 'distinct'])
    if kind in ('join', 'left'):
        cols = ['a.x', 'a.y', 'b.x', 'b.y']
        frm = f"a {'LEFT ' if kind=='left' else ''}JOIN b ON {gen_cond(r, cols)}"
    else:
        cols = ['x', 'y']; frm = 'a'
    where = f" WHERE {gen_cond(r, cols)}" if r.random() < 0.7 else ""
    if kind == 'group':
        g = r.choice(cols)
        agg = r.choice(['COUNT(*)', f'COUNT({cols[1]})', f'SUM({gen_expr(r, cols, 1)})', f'MIN({cols[1]})', f'MAX({cols[0]})', f'COUNT(DISTINCT {cols[0]})'])
        q = f"SELECT {g}, {agg} FROM {frm}{where} GROUP BY {g}"
        if r.random() < 0.4: q += f" HAVING COUNT(*) > {r.randint(0,2)}"
    else:
        sel = ", ".join(gen_expr(r, cols, 1) for _ in range(r.randint(1, 3)))
        q = f"SELECT {'DISTINCT ' if kind=='distinct' else ''}{sel} FROM {frm}{where}"
    try:
        got = m.execute(q)["rows"]
        err = None
    except DBError as e:
        got, err = None, e
    try:
        exp = [list(x) for x in s.execute(q).fetchall()]
    except Exception as e:
        return
    if err is not None:
        # sqlite returns NULL on division by zero; minidb raises
        if type(err).__name__ == 'SQLRuntimeError': return
        print("ERR", seed, q, err, exp); return
    if any(v is None for row in exp for v in row) and '/' in q or '%' in q:
        # sqlite gives NULL for x/0; we would have raised, so mismatch impossible here
        pass
    key = lambda row: [(v is None, v if v is not None else 0) for v in row]
    if kind in ('plain', 'join', 'left'):
        ok = got == exp  # order must match nested-loop/table order
    else:
        ok = sorted(got, key=key) == sorted(exp, key=key)
    if not ok:
        print("DIFF", seed, q, "\n  minidb:", got, "\n  sqlite:", exp)

for seed in range(int(sys.argv[1]), int(sys.argv[2])):
    run(seed)
