    op = r.choice(["+", "-", "*", "/", "%"])
    return f"({_expr(r, cols, depth + 1)} {op} {_expr(r, cols, depth + 1)})"


def _cond(r, cols, depth=0):
    k = r.random()
    if depth > 1 or k < 0.5:
        choice = r.random()
        if choice < 0.15:
