        op = r.choice(["=", "<>", "<", "<=", ">", ">="])
        return f"{_expr(r, cols, 2)} {op} {_expr(r, cols, 2)}"
    if k < 0.65:
        return f"NOT ({_cond(r, cols, depth + 1)})"
    return f"({_cond(r, cols, depth + 1)} {r.choice(['AND', 'OR'])} {_cond(r, cols, depth + 1)})"


